function xmlEscape(s) {
    return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}

function resolveTarget(cfg, target) {
    if (!target) throw new Error('Missing target');
    if (target.startsWith('speaker:')) {
        const id = target.slice(8);
        const speaker = cfg.speakers[id];
        if (!speaker) throw new Error('Unknown speaker ' + id);
        return { type: 'speaker', id, speaker, zoneName: '' };
    }
    if (target.startsWith('zone:')) {
        const id = target.slice(5);
        const zone = cfg.zones[id];
        if (!zone) throw new Error('Unknown zone ' + id);
        const master = cfg.speakers[zone.master];
        if (!master) throw new Error('Unknown zone master ' + zone.master);
        return { type: 'zone', id, zone, speaker: master, speakerId: zone.master, zoneName: zone.name || id };
    }
    throw new Error('Target must start with speaker: or zone:');
}

function liveMetadataSubtitle(metadata, maxAgeSeconds) {
    if (!metadata || !metadata.updated_at) return '';
    const ageSeconds = (Date.now() / 1000) - Number(metadata.updated_at);
    if (!Number.isFinite(ageSeconds) || ageSeconds > maxAgeSeconds) return '';
    if (metadata.artist && metadata.title) return `${metadata.artist} - ${metadata.title}`;
    return metadata.raw || '';
}

function chooseSubtitle(cfg, stationKey, station, target) {
    const liveMetadata = global.get('liveMetadata') || {};
    const candidates = {
        live_metadata: liveMetadataSubtitle(liveMetadata[stationKey], cfg.liveMetadataMaxAgeSeconds || 45),
        zone_name: target.zoneName || '',
        speaker_name: (target.speaker && target.speaker.name) || target.id || '',
        station_owner: station.owner || ''
    };
    const priority = cfg.displaySubtitlePriority || ['live_metadata', 'zone_name', 'speaker_name', 'station_owner'];
    for (const source of priority) {
        if (candidates[source]) return { subtitle: candidates[source], source };
    }
    return { subtitle: '', source: 'empty' };
}

function logoUrl(cfg, station) {
    if (!station || !station.logo) return '';
    if (station.logo.startsWith('http://') || station.logo.startsWith('https://')) return station.logo;
    return `http://${cfg.piIp}:${cfg.proxyPort || 8091}${station.logo}`;
}

async function fetchMetadataIfAvailable(cfg, stationKey, station) {
    if (!station || !station.live_metadata || !station.live_metadata.enabled || !station.live_metadata.endpoint) return;
    try {
        const res = await fetch(`http://${cfg.piIp}:${cfg.proxyPort || 8091}${station.live_metadata.endpoint}`);
        if (!res.ok) return;
        const data = await res.json();
        const liveMetadata = global.get('liveMetadata') || {};
        liveMetadata[stationKey] = data;
        global.set('liveMetadata', liveMetadata);
    } catch (e) {
        // Metadata is optional; playback should never fail because metadata failed.
    }
}

async function soundtouchPost(ip, path, body, contentType='text/xml') {
    const res = await fetch(`http://${ip}${path}`, {
        method: 'POST',
        headers: { 'Content-Type': contentType },
        body
    });
    const text = await res.text();
    if (!res.ok) throw new Error(`${ip}${path} -> ${res.status}: ${text}`);
    return text;
}

async function soap(ip, action, innerXml) {
    const envelope = `<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">
  <s:Body>${innerXml}</s:Body>
</s:Envelope>`;
    const res = await fetch(`http://${ip}:8091/AVTransport/Control`, {
        method: 'POST',
        headers: {
            'Content-Type': 'text/xml; charset="utf-8"',
            'SOAPACTION': `"urn:schemas-upnp-org:service:AVTransport:1#${action}"`
        },
        body: envelope
    });
    const text = await res.text();
    if (!res.ok) throw new Error(`${action} failed on ${ip}: ${res.status}: ${text}`);
    return text;
}

async function applyZone(cfg, zoneId) {
    const zone = cfg.zones[zoneId];
    if (!zone) throw new Error('Unknown zone ' + zoneId);
    const master = cfg.speakers[zone.master];
    if (!master) throw new Error('Unknown zone master ' + zone.master);
    if (!master.device_id) throw new Error('Master speaker needs device_id for Bose zone creation');

    const members = (zone.members || []).map(id => ({ id, speaker: cfg.speakers[id] })).filter(x => x.speaker);
    for (const m of members) {
        if (!m.speaker.device_id) throw new Error(`Zone member ${m.id} needs device_id`);
    }

    const membersXml = members.map(m => `<member ipaddress="${xmlEscape(m.speaker.ip)}">${xmlEscape(m.speaker.device_id)}</member>`).join('');
    const body = `<zone master="${xmlEscape(master.device_id)}">${membersXml}</zone>`;
    const result = await soundtouchPost(master.ip + ':8090', '/setZone', body);
    return { master: zone.master, members: members.map(m => m.id), result };
}

async function playOnSpeaker(speaker, name, streamUrl, display) {
    const subtitleXml = display.subtitle ? `<dc:creator>${xmlEscape(display.subtitle)}</dc:creator><upnp:artist>${xmlEscape(display.subtitle)}</upnp:artist>` : '';
    const albumXml = display.album ? `<upnp:album>${xmlEscape(display.album)}</upnp:album>` : '';
    const artXml = display.logo ? `<upnp:albumArtURI>${xmlEscape(display.logo)}</upnp:albumArtURI>` : '';
    const didl = `<DIDL-Lite xmlns="urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:upnp="urn:schemas-upnp-org:metadata-1-0/upnp/" xmlns:dlna="urn:schemas-dlna-org:metadata-1-0/">
  <item id="${xmlEscape(name)}" parentID="0" restricted="1">
    <dc:title>${xmlEscape(name)}</dc:title>
    ${subtitleXml}
    ${albumXml}
    ${artXml}
    <upnp:class>object.item.audioItem.audioBroadcast</upnp:class>
    <res protocolInfo="http-get:*:audio/mpeg:DLNA.ORG_PN=MP3">${xmlEscape(streamUrl)}</res>
  </item>
</DIDL-Lite>`;
    const setUri = await soap(speaker.ip, 'SetAVTransportURI', `<u:SetAVTransportURI xmlns:u="urn:schemas-upnp-org:service:AVTransport:1"><InstanceID>0</InstanceID><CurrentURI>${xmlEscape(streamUrl)}</CurrentURI><CurrentURIMetaData>${xmlEscape(didl)}</CurrentURIMetaData></u:SetAVTransportURI>`);
    await new Promise(resolve => setTimeout(resolve, 300));
    const play = await soap(speaker.ip, 'Play', `<u:Play xmlns:u="urn:schemas-upnp-org:service:AVTransport:1"><InstanceID>0</InstanceID><Speed>1</Speed></u:Play>`);
    return { setUri, play };
}

